import type { ComboboxContentProps } from "../combobox.types";

import React, { forwardRef } from "react";
import { FloatingPortal } from "@floating-ui/react";
import { useTheme } from "@theme";
import { clsx } from "clsx";
import { assignRef, flattenChildren } from "@system";

import { useComboboxState } from "../hooks/use-combobox-state";
import { useComboboxFloating } from "../hooks/use-combobox-floating";
import { ComboboxClasses, StyledCombobox } from "../combobox.styles";

import { ComboboxGroup } from "./combobox-group";
import { ComboboxItem } from "./combobox-item";

const ComboboxContent = forwardRef<HTMLDivElement, ComboboxContentProps>(
  ({ children, className, style, ...props }, ref) => {
    const { styleSlots, variant, noResults, as } = useComboboxState();
    const { refs, floatingStyles, getFloatingProps, isMounted, listRef } = useComboboxFloating();
    const theme = useTheme();
    const childrenArray = flattenChildren(children);
    const groupedChildren: React.ReactNode[] = [];
    let currentGroup: React.ReactNode[] = [];
    const hasChildren = childrenArray.length > 0;

    const isGroup = (child: React.ReactNode) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string })?.displayName?.endsWith("Group");

    const isDivider = (child: React.ReactNode) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string })?.displayName?.endsWith("Divider");

    const isItem = (child: React.ReactNode) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string })?.displayName?.endsWith("Item");

    const flushGroup = () => {
      if (currentGroup.length > 0) {
        groupedChildren.push(
          <ComboboxGroup key={groupedChildren.length}>{currentGroup}</ComboboxGroup>,
        );
        currentGroup = [];
      }
    };

    childrenArray.forEach((child, index) => {
      if (isGroup(child) || isDivider(child)) {
        flushGroup();
        groupedChildren.push(child);
      } else if (isItem(child)) {
        currentGroup.push(
          React.cloneElement(child as React.ReactElement, {
            key: index,
            ref: (node: HTMLElement | null) => {
              listRef.current[index] = node;
              assignRef((child as React.ReactElement).props.ref, node);
            },
          }),
        );
      } else {
        currentGroup.push(
          <ComboboxItem
            key={index}
            ref={(node: HTMLElement | null) => {
              listRef.current[index] = node;
            }}
            {...(child as React.ReactElement).props}
          />,
        );
      }
    });

    flushGroup();

    if (!isMounted) {
      return null;
    }

    return (
      <FloatingPortal>
        <div
          ref={refs.setFloating}
          style={{ zIndex: theme?.zIndex?.dynamic, ...floatingStyles }}
          {...getFloatingProps(props)}
        >
          <StyledCombobox
            ref={ref}
            as={as}
            className={clsx(ComboboxClasses.content, className)}
            currentTheme={theme}
            role="listbox"
            style={style}
            styleSlots={styleSlots}
            variant={variant}
          >
            {hasChildren ? (
              groupedChildren
            ) : (
              <div className={ComboboxClasses.noResults}>{noResults}</div>
            )}
          </StyledCombobox>
        </div>
      </FloatingPortal>
    );
  },
);

ComboboxContent.displayName = "Combobox.Content";

export { ComboboxContent };
